import SwiftUI
import Observation
@Observable final class SettingsModel {
    let id = 5
    var notifications = false
}
struct SettingsScreen: View {
    @State private var settings = SettingsModel()
    var body: some View {
        VStack {
            Text("Включены: \(settings.notifications)")
            SettingsEditor(settings: settings)
        }
    }
}
struct SettingsEditor: View {
    @Bindable var settings: SettingsModel
    var body: some View {
        Toggle("Уведомления", isOn: $settings.notifications)
    }
}

import SwiftUI
final class CounterModel: ObservableObject {
    let id = 9
    @Published var count = 2
}
struct CounterScreen: View {
    @StateObject private var counter = CounterModel()
    var body: some View {
        VStack {
            Text("Цель: \(counter.count)")
            CounterEditor()
        }
    }
}
struct CounterEditor: View {
    @StateObject private var counter = CounterModel()
    var body: some View {
        Stepper("Цель: \(counter.count)", value: $counter.count, in: 0...5)
    }
}

